import{_ as e,o as n,c as a,ah as s}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Cafeteria and transport","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/vie-scolaire/cantine-et-transport.md","filePath":"src/en/guide/vie-scolaire/cantine-et-transport.md"}'),r={name:"en/guide/vie-scolaire/cantine-et-transport.md"};function o(i,t,c,l,d,g){return n(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="cafeteria-and-transport" tabindex="-1">Cafeteria and transport <a class="header-anchor" href="#cafeteria-and-transport" aria-label="Permalink to &quot;Cafeteria and transport&quot;">​</a></h1><p>This page covers running the cafeteria (menus and attendance) and tracking school transport (assigning students to routes and taking their attendance). The transport routes themselves are created by the administrator; as school life staff, you assign students to existing routes and take their attendance at pickup and drop-off.</p><h2 id="manage-cafeteria-menus" tabindex="-1">Manage cafeteria menus <a class="header-anchor" href="#manage-cafeteria-menus" aria-label="Permalink to &quot;Manage cafeteria menus&quot;">​</a></h2><ol><li>Open <strong>Student services → Cafeteria menus</strong>, then click <strong>New menu</strong>.</li><li>Choose the <strong>Site</strong> and <strong>Date</strong> concerned.</li><li>Describe the content in <strong>Menu</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The list of menus can be filtered by site. <strong>Edit</strong> lets you fix the date or content of an already published menu; <strong>Delete</strong> permanently removes it after confirmation — this cannot be undone.</p><h2 id="take-cafeteria-attendance" tabindex="-1">Take cafeteria attendance <a class="header-anchor" href="#take-cafeteria-attendance" aria-label="Permalink to &quot;Take cafeteria attendance&quot;">​</a></h2><p><strong>Student services → Cafeteria attendance</strong> shows, for the date selected at the top of the page (the current day by default), the list of students currently subscribed to the cafeteria. For each one, tap <strong>Ate</strong> or <strong>Absent</strong>, then click <strong>Save</strong> to record the whole day&#39;s attendance at once. If no student is subscribed, the page says so.</p><div class="tip custom-block"><p class="custom-block-title">A roll call built for phones</p><p>Each student has a <strong>Ate</strong> / <strong>Absent</strong> switch; everyone starts as <strong>Ate</strong>, and the <strong>Everyone ate</strong> button resets the whole list to that status. The counters above the list update on every tap, and the bottom bar shows &quot;Unsaved changes&quot; until you click <strong>Save</strong> — leaving the page or changing the date at that point asks for confirmation. Attendance can&#39;t be recorded for a future date.</p></div><h2 id="assign-students-to-transport-routes" tabindex="-1">Assign students to transport routes <a class="header-anchor" href="#assign-students-to-transport-routes" aria-label="Permalink to &quot;Assign students to transport routes&quot;">​</a></h2><ol><li>Open <strong>Student services → Route assignments</strong>, then click <strong>New assignment</strong>.</li><li>Choose the <strong>Student</strong> (only students not yet assigned to a route are offered) then the transport <strong>Route</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The list of assignments can be filtered by route. <strong>Unassign</strong> removes a student from their route after confirmation.</p><h2 id="take-transport-attendance" tabindex="-1">Take transport attendance <a class="header-anchor" href="#take-transport-attendance" aria-label="Permalink to &quot;Take transport attendance&quot;">​</a></h2><ol><li>Open <strong>Student services → Transport attendance</strong>, which lists routes with their site. Click <strong>Take attendance</strong> on the relevant route.</li><li>Choose the <strong>date</strong> and the <strong>direction</strong> of the trip — <strong>Pickup</strong> or <strong>Drop-off</strong> — at the top of the page.</li><li>For each student assigned to the route, tap <strong>Present</strong> or <strong>Absent</strong> — the <strong>Everyone present</strong> button resets the whole list to present.</li><li>Click <strong>Save</strong>.</li></ol><p>If no student is assigned to the route, the page says so. This roll call works like the cafeteria one (see the tip above).</p>',14)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
